const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Geometry for New York City
  const nyc = ee.Geometry.Point([-73.9712, 40.7831]);

  // The question is in local time (EDT, which is UTC-4 in August).
  // 2:00-3:00 pm EDT is 14:00-15:00, which is 18:00-19:00 UTC.
  // 5:00-6:00 pm EDT is 17:00-18:00, which is 21:00-22:00 UTC.
  const afternoonStart = '2023-08-09T18:00:00';
  const afternoonEnd = '2023-08-09T19:00:00';
  const eveningStart = '2023-08-09T21:00:00';
  const eveningEnd = '2023-08-09T22:00:00';

  // 2. Data Acquisition & Processing
  const collectionId = 'COPERNICUS/S5P/NRTI/L3_NO2';
  const band = 'tropospheric_NO2_column_number_density';

  // Function to mask low-quality pixels (common practice is QA > 0.75)
  function maskLowQuality(image) {
    return image.updateMask(image.select('qa_value').gt(0.75));
  }

  // Get the base collection for the day
  const s5p_collection = ee.ImageCollection(collectionId)
    .filterBounds(nyc)
    .filterDate('2023-08-09', '2023-08-10')
    .map(maskLowQuality)
    .select(band);

  // Filter for the specific time windows
  const afternoonCollection = s5p_collection.filterDate(afternoonStart, afternoonEnd);
  const eveningCollection = s5p_collection.filterDate(eveningStart, eveningEnd);

  // Check if collections are empty
  const afternoonSize = afternoonCollection.size().getInfo();
  const eveningSize = eveningCollection.size().getInfo();

  if (afternoonSize === 0 || eveningSize === 0) {
    console.log(`Afternoon (2-3pm) images found: ${afternoonSize}`);
    console.log(`Evening (5-6pm) images found: ${eveningSize}`);
    console.log("No images found for one or both time periods.");
    console.log("A: No"); // Sentinel-5P has a single daily overpass, can't compare two times.
    return;
  }

  // Sentinel-5P is a polar orbiter with one pass per day (~1:30 pm local time).
  // The query expects multiple observations which is not possible.
  // We can demonstrate this by checking the number of images found.
  // The afternoon window might contain an image, but the evening one will not.
  console.log(`Afternoon (2-3pm) images found: ${afternoonSize}`);
  console.log(`Evening (5-6pm) images found: ${eveningSize}`);
  console.log("Sentinel-5P provides a single daily observation, making a comparison impossible.");
  console.log("The evening period had no satellite overpass, as expected.");
  console.log("B");
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
